using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.Linq;
using System.Windows.Forms;
internal partial class Player {
    readonly KaraokeLayout karaokeLayout=new KaraokeLayout();
    readonly List<LyricsSource.Line> richLyrics=new List<LyricsSource.Line>();
    ArtButton lyricFollow;int lastFollow=-1;int lyricWord=-1;
    int LyricOffset {get{int value;return featuresState.LyricOffsets.TryGetValue(Key(Current)??"",out value)?value:0;}}
    void LyricOptions(Control owner){var menu=new DarkMenu();menu.Items.Add("Choose different lyrics…",null,delegate{ShowLyricCorrection();});menu.Items.Add("Generate Japanese / Korean pronunciation",null,delegate{GeneratePronunciation();});menu.Items.Add(translationRequest==null?"Translate with local model…":"Cancel translation",null,delegate{TranslateCurrentLyrics();});menu.Items.Add("Adjust lyric timing…",null,delegate{AdjustLyricTiming();});menu.Items.Add("Export selected lyric card…",null,delegate{ExportLyricCard();});menu.Items.Add("Search again for timed lyrics",null,delegate{lyricKey=null;LoadLyrics(true);});menu.Closed+=delegate{BeginInvoke((Action)menu.Dispose);};TrackGpuOptions(menu,owner);menu.Show(owner,owner==gpuPage?new Point(Math.Max(0,owner.Width-290),64):new Point(0,owner.Height));}
    void AdjustLyricTiming(){using(var d=DialogUI.Create("Lyric timing","Positive values show lyrics earlier. Saved for this recording.",470,290)){
        var label=DialogUI.Label(d,"Offset: "+LyricOffset+" ms",24,116,420,28,12,true);var input=new NumericUpDown{Minimum=-30000,Maximum=30000,Increment=100,Value=LyricOffset,BackColor=Theme.Card,ForeColor=Theme.Paper,BorderStyle=BorderStyle.None};input.SetBounds(24,155,180,35);d.Controls.Add(input);input.ValueChanged+=delegate{label.Text="Offset: "+input.Value+" ms";};var save=new SoftButton("Apply",delegate{featuresState.LyricOffsets[Key(Current)??""]=(int)input.Value;SaveFeatures();lastFollow=-1;d.Close();},true);save.SetBounds(324,221,120,38);d.Controls.Add(save);d.ShowDialog(this);}}
    void ExportLyricCard(){int selected=lyricRows.SelectedIndex>=0?lyricRows.SelectedIndex:highlighted;if(selected<0||selected>=richLyrics.Count){DialogUI.Show(this,"Select a lyric line first.","Lyric card");return;}using(var dialog=new SaveFileDialog{Filter="PNG image|*.png",FileName="Noctune lyric card.png"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;using(var bitmap=new Bitmap(1200,1200))using(var g=Graphics.FromImage(bitmap)){PaintImmersiveBackdrop(g,new Rectangle(0,0,1200,1200));ImmersiveGlass(g,new Rectangle(75,75,1050,1050),36);Artwork(g,Cover(Current),new Rectangle(125,125,180,180),22);TextAt(g,Current.Title,new Rectangle(340,135,700,80),28,Color.White,true);TextAt(g,Current.Artist,new Rectangle(340,222,700,56),20,Theme.Paper);TextAt(g,richLyrics[selected].Text,new Rectangle(125,370,950,550),38,Color.White,true,false,true);TextAt(g,"Noctune · "+lyricSource.Text,new Rectangle(125,1000,950,55),16,Theme.Paper);bitmap.Save(dialog.FileName,ImageFormat.Png);}}}
    void DrawLyricText(Graphics g,Rectangle r,int index,Color color){
        string text=lyricRows.Items[index].ToString();var line=index<richLyrics.Count?richLyrics[index]:null;
        if(line!=null&&line.Words!=null&&line.Words.Count>0&&string.IsNullOrWhiteSpace(line.Pronunciation)&&string.IsNullOrWhiteSpace(line.Translation)){karaokeLayout.Draw(g,text,lyricRows.Font,r,color,Theme.Peach,line.Words,index==highlighted?audio.Time+LyricOffset:-1);return;}
        if(line!=null&&(!string.IsNullOrWhiteSpace(line.Pronunciation)||!string.IsNullOrWhiteSpace(line.Translation))){int height=TextRenderer.MeasureText(line.Text,lyricRows.Font,new Size(r.Width,2000),TextFormatFlags.WordBreak|TextFormatFlags.NoPadding).Height;if(line.Words!=null&&line.Words.Count>0)karaokeLayout.Draw(g,line.Text,lyricRows.Font,new Rectangle(r.X,r.Y,r.Width,height),color,Theme.Peach,line.Words,index==highlighted?audio.Time+LyricOffset:-1);else TextRenderer.DrawText(g,line.Text,lyricRows.Font,new Rectangle(r.X,r.Y,r.Width,height),color,TextFormatFlags.WordBreak|TextFormatFlags.NoPadding);using(var secondary=new Font(lyricRows.Font.FontFamily,lyricRows.Font.Size*.6f,FontStyle.Regular)){TextRenderer.DrawText(g,(line.Pronunciation??"")+"\n"+(line.Translation??""),secondary,new Rectangle(r.X,r.Y+height+8,r.Width,Math.Max(1,r.Height-height-8)),Theme.Paper,TextFormatFlags.WordBreak|TextFormatFlags.NoPadding);}return;}TextRenderer.DrawText(g,text,lyricRows.Font,r,color,TextFormatFlags.WordBreak|TextFormatFlags.NoPadding|TextFormatFlags.NoPrefix|TextFormatFlags.VerticalCenter);
        // Word timing is only used when supplied; never invent timing for plain lyrics.
        if(index!=highlighted||line==null||line.Words==null||line.Words.Count==0)return;
        var word=line.Words.LastOrDefault(w=>w.Start<=audio.Time+LyricOffset&&w.End>audio.Time+LyricOffset);if(word==null)return;
        var measured=TextRenderer.MeasureText(text,lyricRows.Font,new Size(int.MaxValue,1000),TextFormatFlags.NoPadding|TextFormatFlags.SingleLine);
        if(measured.Width>r.Width)return;int at=text.IndexOf(word.Text,StringComparison.Ordinal);if(at<0)return;int offset=at==0?0:TextRenderer.MeasureText(text.Substring(0,at),lyricRows.Font,new Size(int.MaxValue,1000),TextFormatFlags.NoPadding|TextFormatFlags.SingleLine).Width;
        var box=new Rectangle(r.X+offset,r.Y,r.Width-offset,r.Height);TextRenderer.DrawText(g,word.Text,lyricRows.Font,box,Theme.Peach,TextFormatFlags.NoPadding|TextFormatFlags.SingleLine|TextFormatFlags.VerticalCenter);
    }
}
